require_once __DIR__.'/core/bootstrap.php';$user=require_login($pdo);$id=(string)($_GET['id']??'');$s=$pdo->prepare("SELECT c.*,u.username creator FROM contests c LEFT JOIN users u ON u.id=c.created_by WHERE c.id=:id");$s->execute(['id'=>$id]);$contest=$s->fetch();if(!$contest){http_response_code(404);exit('Contest not found');}$p=$pdo->prepare("SELECT p.*,cp.points FROM contest_problems cp JOIN problems p ON p.id=cp.problem_id WHERE cp.contest_id=:id ORDER BY cp.points");$p->execute(['id'=>$id]);$problems=$p->fetchAll();$l=$pdo->prepare("SELECT cp.score,u.username,u.rating FROM contest_participants cp JOIN users u ON u.id=cp.user_id WHERE cp.contest_id=:id ORDER BY cp.score DESC,u.rating DESC");$l->execute(['id'=>$id]);$board=$l->fetchAll();$pageTitle=$contest['name'];include __DIR__.'/includes/header.php';?>
<div class="page-head"><div><div class="eyebrow"><?=e($contest['type'])?> Contest</div><h1><?=e($contest['name'])?></h1><p><?=e($contest['starts_at'])?> · Created by <?=e($contest['creator']??'System')?></p></div><span class="pill <?=$contest['status']==='Active'?'pill-easy':'pill-neutral'?>"><?=e($contest['status'])?></span></div>
